import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';

// `@visual` runs in every viewport × theme project with the clock frozen (fixtures/clock.ts).
// Baselines live in e2e/__screenshots__ and are only ever generated by the e2e workflow's
// `update_snapshots` dispatch in the pinned Playwright image (see README.md).
test('sign-in', { tag: '@visual' }, async ({ page }, testInfo) => {
  const baseline = testInfo.snapshotPath('sign-in.png', { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
  await page.goto('/sign-in');
  await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
  await expect(page).toHaveScreenshot('sign-in.png', {
    fullPage: true,
    mask: [page.locator('[data-testid="dynamic"]')],
  });
});
